"""Summarize all 64 frozen top-pick disagreements, with 66 agreements as context."""
import json,pathlib,collections,csv,re,statistics,hashlib,sys
root=pathlib.Path(__file__).resolve().parent;data=json.load(open(root/'DEEP_INPUT_AUDIT.json'));rs=data['rows'];ds=[r for r in rs if r['disagreement']]
def totals(rows):return {'races':len(rows),'v44c_winners':sum(r['control_metrics']['win']for r in rows),'finisher_winners':sum(r['finisher_metrics']['win']for r in rows),'v44c_coverage':sum(r['control_metrics']['coverage']for r in rows),'finisher_coverage':sum(r['finisher_metrics']['coverage']for r in rows),'v44c_slots':sum(r['control_metrics']['slots']for r in rows),'finisher_slots':sum(r['finisher_metrics']['slots']for r in rows)}
def driver_margins(r):
 hs={h['id']:h for h in r['horses']};v=hs[r['control'][0]];f=hs[r['finisher'][0]]
 fd={k:(f['finisher_components'][k]['percentile']-v['finisher_components'][k]['percentile'])*f['finisher_components'][k]['weight']for k in f['finisher_components']}
 vc=v['control_contributions'];fc=f['control_contributions'];vd={'Latest speed':vc['latest']-fc['latest'],'Best3 speed':vc['best3']-fc['best3'],'Connections':sum(vc.get(k,0)-fc.get(k,0)for k in ['jockey_win','trainer_win','trainer_context_score']),'Adjustments':vc['adjustment_residual']-fc['adjustment_residual']}
 assert abs(sum(fd.values())-(f['finisher_score']-v['finisher_score']))<1e-7;assert abs(sum(vd.values())-(v['control_score']-f['control_score']))<1e-7
 return {'finisher_margin_components':fd,'v44c_margin_components':vd,'dominant_finisher_component':max(fd,key=fd.get),'dominant_v44c_component':max(vd,key=vd.get),'control_pick':v,'finisher_pick':f}
for r in ds:r.update(driver_margins(r))
headers=[]
for r in rs:
 line=next((l for l in r['header'].split('\n')if re.search(r'\b(?:MILES?|Furlongs)\b',l,re.I)and not re.match(r'^\s*(if|alternate)',l,re.I)),'')
 if not re.search(r'\b(\d+[Â±²°ô¶ó]?)\s+(MILES?|Furlongs)',line,re.I):headers.append({'key':r['key'],'disagreement':r['disagreement'],'outcome':r['outcome'],'header_line':line,'all_matching_speed_unknown':all(h['stored_features']['matched_speed']is None for h in r['horses'])})
summary={'scope':'Frozen retrospective diagnostic; no model, weight, eligibility, parser or production changes. No new selection rules are tested.','all':totals(rs),'disagree':totals(ds),'agree':totals([r for r in rs if not r['disagreement']]),'correct_slots':{key:[sum(r[key][i]==r['actual'][i]for r in rs)for i in range(4)]for key in ['control','finisher']},'groups':{},'feature_reproduction':{'races':len(rs),'runners':sum(len(r['horses'])for r in rs),'mismatched_runner_features':sum(bool(h['feature_mismatch'])for r in rs for h in r['horses']),'recent_sequence_fallback_runners':sum(h['recent_fallback']for r in rs for h in r['horses'])},'undecoded_today_distance':headers,'source_pdf_visual_check':{'file':'Saratoga_Ten_Card_Retest_Evidence/upload/SAR--07-12-2026.pdf','pdf_page':3,'printed_distance_miles':'1 1/2','stored_header':'1 ¶ MILES','effect':'Today-distance regex does not parse this line; matching speed is unknown throughout the field.','winner':'Malibu Smart','v44c_rank':8,'finisher_rank':8},'potential_past_distance_issue':json.load(open(root/'DISTANCE_ENCODING_FLAGS.json')),'all_64_cases':ds}
for outcome in ['Finisher','V4.4c','Neither']:
 cs=[r for r in ds if r['outcome']==outcome];summary['groups'][outcome]={**totals(cs),'finisher_score_driver':dict(collections.Counter(r['dominant_finisher_component']for r in cs)),'v44c_score_driver':dict(collections.Counter(r['dominant_v44c_component']for r in cs)),'picked_runner_recent_fallback_cases':sum(r['control_pick']['recent_fallback']or r['finisher_pick']['recent_fallback']for r in cs),'either_pick_missing_matching_speed':sum(any(r[key]['stored_features']['matched_speed']is None for key in ['control_pick','finisher_pick'])for r in cs)}
ns=[r for r in ds if r['outcome']=='Neither'];summary['neither_winner_coverage']={'winner_both_top4':sum(r['actual'][0]in r['control'][:4]and r['actual'][0]in r['finisher'][:4]for r in ns),'winner_only_finisher_top4':sum(r['actual'][0]not in r['control'][:4]and r['actual'][0]in r['finisher'][:4]for r in ns),'winner_only_v44c_top4':sum(r['actual'][0]in r['control'][:4]and r['actual'][0]not in r['finisher'][:4]for r in ns),'winner_neither_top4':sum(r['actual'][0]not in r['control'][:4]and r['actual'][0]not in r['finisher'][:4]for r in ns)}
assert len(ds)==64;assert summary['disagree']['finisher_winners']==18;assert summary['disagree']['v44c_winners']==12
(root/'DEEP_DISAGREEMENT_REVIEW.json').write_text(json.dumps(summary,indent=2))
with open(root/'ALL_64_DISAGREEMENTS.csv','w',newline='')as f:
 w=csv.writer(f);w.writerow(['race','cohort','surface','field','v44c_pick','finisher_pick','actual_winner','outcome','v44c_coverage','finisher_coverage','v44c_slots','finisher_slots','finisher_score_driver','v44c_score_driver'])
 for r in ds:
  hs={h['id']:h for h in r['horses']};w.writerow([r['key'],r['cohort'],r['surface'],len(r['horses']),r['control_pick']['name'],r['finisher_pick']['name'],hs[r['actual'][0]]['name'],r['outcome'],r['control_metrics']['coverage'],r['finisher_metrics']['coverage'],r['control_metrics']['slots'],r['finisher_metrics']['slots'],r['dominant_finisher_component'],r['dominant_v44c_component']])
print(json.dumps({k:v for k,v in summary.items()if k not in ['all_64_cases']},indent=2))
